import{_ as t,a,c as o,ac as n}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse(`{"title":"第二册：实践与进步 · Lesson 75 SOS","description":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第二册：实践与进步 · Lesson 75 SOS","description":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第2册课时","summary":"学习 不定式与目的，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · Lesson 74 Out of the limelight","link":"/life/english/new-concept/book-2/unit-04/lesson-074"},"next":{"text":"第二册：实践与进步 · Lesson 76 April Fools' Day","link":"/life/english/new-concept/book-2/unit-04/lesson-076"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · Lesson 74 Out of the limelight","link":"/life/english/new-concept/book-2/unit-04/lesson-074"},"next":{"text":"第二册：实践与进步 · Lesson 76 April Fools' Day","link":"/life/english/new-concept/book-2/unit-04/lesson-076"}},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/lesson-075.md","filePath":"life/english/new-concept/book-2/unit-04/lesson-075.md"}`),i={name:"life/english/new-concept/book-2/unit-04/lesson-075.md"};function l(s,e,r,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="第二册-实践与进步-·-lesson-75-sos" tabindex="-1">第二册：实践与进步 · Lesson 75 SOS <a class="header-anchor" href="#第二册-实践与进步-·-lesson-75-sos" aria-label="Permalink to &quot;第二册：实践与进步 · Lesson 75 SOS&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-2/contents">本册目录</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>紧急求助信息必须简短明确，位置、人数和需求缺一不可；练习目的不定式与被动救援。本课的语言观察是：to attract attention 表摆放标记的目的；目的主语与放置者相同。so that 从句可更明确引出另一执行者，如 pilots could see it。完成学习后，请写三句模拟求助信息，给出地点、人数、无法移动的情况；不虚构真实救援呼叫。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>helicopter</td><td>/ˈhelɪkɒptə/</td><td>n.</td><td>直升机</td><td>a rescue helicopter</td></tr><tr><td>survivor</td><td>/səˈvaɪvə/</td><td>n.</td><td>幸存者</td><td>an accident survivor</td></tr><tr><td>message</td><td>/ˈmesɪdʒ/</td><td>n.</td><td>消息</td><td>send a message</td></tr><tr><td>urgent</td><td>/ˈɜːdʒənt/</td><td>adj.</td><td>紧急的</td><td>an urgent request</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>call for help — 呼救、请求援助</li><li>in need of — 需要，of 后接名词</li></ul><h2 id="语法讲解-不定式与目的" tabindex="-1">语法讲解：不定式与目的 <a class="header-anchor" href="#语法讲解-不定式与目的" aria-label="Permalink to &quot;语法讲解：不定式与目的&quot;">​</a></h2><p>to 加动词原形可以作某些动词的宾语、名词后的修饰语或表示目的的状语。表示目的时，执行不定式动作的人通常与主句主语一致；不一致时需明确另一个逻辑主语，如 for somebody to do。否定一般写 not to do。情态动词后、make/let 主动结构中通常用不带 to 的原形，不能因为看到两个动词就一律在中间加入 to。本课应用：to attract attention 表摆放标记的目的；目的主语与放置者相同。so that 从句可更明确引出另一执行者，如 pilots could see it。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The hikers laid bright jackets on the rocks to attract attention.</p></blockquote><p>徒步者把鲜艳的外套铺在岩石上，以吸引注意。</p><p>laid 为 lay 的过去式，bright jackets 是宾语，to attract 为目的状语，执行者与 hikers 一致。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>重读地点和 one person，区分 laid /leɪd/ 与 lay /leɪ/，保持信息清晰。可朗读本页原创示范并自行录音回听；本页不提供教材录音。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The hikers laid bright jackets on the rocks to attract attention. A helicopter crew spotted the colours. The hikers signalled that one person could not walk.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句模拟求助信息，给出地点、人数、无法移动的情况；不虚构真实救援呼叫。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>第一句的组织方式：laid 为 lay 的过去式，bright jackets 是宾语，to attract 为目的状语，执行者与 hikers 一致。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：lie 表躺下，过去式 lay；lay 表放置，过去式 laid，本例需要有宾语的 laid。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填 lay 的过去式：They ___ jackets on the rocks.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> laid</p><p><strong>解析：</strong> lay 表放置，过去式为 laid。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>有几个人无法行走？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> One.</p><p><strong>解析：</strong> 求救信息明确 one person，不可放大为全部人受伤。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>用 so that 改写 They used bright jackets to attract the pilots&#39; attention。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> They used bright jackets so that the pilots could see them.</p><p><strong>解析：</strong> 目的从句明确另一个动作执行者 pilots。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：不定式与目的。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-2/unit-04/lesson-074">上一课</a> · <a href="/life/english/new-concept/book-2/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-2/unit-04/lesson-076">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const k=t(i,[["render",l]]);export{u as __pageData,k as default};
